export async function currentWeather(city, apiKey, fetchImpl = fetch) {
  const response = await fetchImpl('https://weather.example/v1/current?city=' + encodeURIComponent(city), { headers: { authorization: 'Bearer ' + apiKey } });
  if (!response.ok) throw new Error('Weather provider returned ' + response.status);
  const body = await response.json();
  return { temperatureC: Number(body.temperatureC), observedAt: body.observedAt };
}

