export function loadConfig(env) {
  const timeoutMs = Number(env.WEATHER_TIMEOUT_MS || 3000);
  if (!env.WEATHER_API_KEY) throw new Error('WEATHER_API_KEY is required');
  if (!Number.isInteger(timeoutMs) || timeoutMs < 100) throw new Error('WEATHER_TIMEOUT_MS must be at least 100');
  return { port: Number(env.PORT || 3000), weatherApiKey: env.WEATHER_API_KEY, timeoutMs };
}

