export class RetryingPetClient {
  constructor(private readonly inner: PetApi, private readonly retries = 2) {}
  async execute<T>(operation: (client: PetApi) => Promise<T>): Promise<T> {
    let lastError: unknown;
    for (let attempt = 0; attempt <= this.retries; attempt++) {
      try { return await operation(this.inner); } catch (error) { lastError = error; }
    }
    throw lastError;
  }
}

