import type { Inventory } from './inventory.js';
export class WarehouseUnavailable extends Error {}
export async function readInventory(baseUrl: string, sku: string, signal?: AbortSignal): Promise<Inventory> {
  const response = await fetch(baseUrl + '/inventory/' + encodeURIComponent(sku), { signal, headers: { accept: 'application/json' } });
  if (response.status === 404) return { sku, available: 0 };
  if (!response.ok) throw new WarehouseUnavailable('Warehouse returned ' + response.status);
  const payload: unknown = await response.json();
  if (!payload || typeof payload !== 'object' || !('available' in payload)) throw new WarehouseUnavailable('Invalid warehouse response');
  return { sku, available: Number(payload.available) };
}

